    {"원어": "ἀκούσαντες (아쿠산테스)", "의미_문법": "들은 - 아오리스트 분사 능동 주격 복수. 한번의 듣는 사건", "설교포인트": "바울은 직접 보지 못했지만 믿음의 소식을 들었다. 복음의 역사는 전문(傳聞)으로도 감사를 낳는다"}
