    {"원어": "ἐν πνεύματι (엔 프뉴마티)", "의미_문법": "성령 안에서 - 전치사구. 성령의 역사 가운데", "설교포인트": "골로새 성도들의 사랑은 성령 안에서의 사랑이었다. 참된 사랑은 성령의 열매이다(갈 5:22)"},
    {"원어": "ἀγάπην (아가펜)", "의미_문법": "사랑 - 명사 여성 단수 대격. 무조건적 헌신의 사랑", "설교포인트": "성령 안에서의 사랑은 감정이 아닌 의지적 헌신이다. 이 사랑이 교회 공동체를 세운다"}
