    {"항목": "바울의 중보기도 내용", "내용": "바울의 기도 내용은 추상적이지 않고 구체적이었다. 신령한 지혜, 하나님의 뜻을 아는 것, 주께 합당한 삶 등 명확한 목표를 가진 기도를 드렸다", "목회적활용": "중보기도는 일반적 복을 구하는 것보다 구체적인 영적 성장을 위해 드려야 효과적이다"}
