    {"원어": "αὐξανόμενοι (아욱사노메노이)", "의미_문법": "자라게 하시고 - 현재 분사 수동 주격 복수. 계속적 성장", "설교포인트": "하나님을 아는 것에서의 성장은 멈추지 않아야 한다. 영적 성장은 평생의 과정이다"}
