    {"항목": "열매 맺음과 자람의 현재 진행형", "내용": "열매를 맺고 자라는 것이 현재 분사로 표현됨은 지속적 과정임을 보여준다. 신앙 성장은 완성된 상태가 아닌 계속되는 과정이다", "목회적활용": "성도들이 자신의 영적 상태에 안주하지 않고 계속 성장하도록 격려해야 한다"}
