    {"항목": "빛과 어둠의 이원론", "내용": "빛 가운데서의 기업은 어둠의 권세와 대조된다(13절). 쿰란 공동체와 초대 교회 모두 빛과 어둠의 이원론을 사용했지만 기독교는 이를 창조론적으로 이해한다", "목회적활용": "우리는 빛의 자녀로 부르심받았다. 어두운 세상에서 빛의 자녀로 사는 것이 성도의 정체성이다"}
