    {"구분": "레위 지파의 하나님이 기업", "내용": "레위 지파는 땅 대신 하나님이 기업이었다(민 18:20). 성도들이 빛 가운데서 하나님 자신을 기업으로 받는 것의 예표이다", "그리스도연결": "예수님이 참 레위인으로서 아버지가 기업이 되심을 완성하셨다. 우리의 기업은 그리스도 안에서 하나님 자신이시다"}
