    {"대지": "서론", "내용": "상속은 공로로 받는 것이 아닌 관계로 받는 것이다. 성도의 기업은 그리스도 안에서의 관계로 받는 영원한 유산이다. 아버지께서 우리를 그 기업에 합당하게 하셨다", "예화_적용": "왕자는 공로로 왕국을 상속받지 않는다. 아버지의 아들이기에 상속받는다. 우리도 하나님의 자녀이기에 기업을 받는다"},
    {"대지": "1대지: 합당하게 하신 하나님의 은혜 (은혜)", "내용": "우리 스스로는 기업에 합당하지 않다. 그러나 아버지께서 우리를 합당하게 하셨다. 이 은혜가 감사의 첫 번째 이유이다", "예화_적용": "흠이 있는 도자기를 금으로 채워 더 아름답게 하는 일본의 킨츠기 기법처럼, 하나님은 우리의 약함을 은혜로 채워 합당하게 하신다"},
    {"대지": "2대지: 빛 가운데 있는 성도의 기업 (정체성)", "내용": "성도의 기업은 빛 가운데 있다. 우리는 빛의 자녀이다. 어둠이 아닌 빛 가운데 사는 것이 성도의 정체성이다", "예화_적용": "밤하늘의 별처럼, 빛 가운데 사는 성도는 어두운 세상을 밝힌다"},
    {"대지": "3대지: 기업을 향한 감사 (감사)", "내용": "기업을 받기에 합당하게 하신 아버지께 감사하라. 구원의 감사, 기업의 감사, 합당하게 하심의 감사가 성도의 삶을 채워야 한다", "예화_적용": "평생 감사하며 사는 사람이 가장 행복하다. 성도의 감사는 기업을 주신 하나님을 향한 것이어야 한다"},
    {"대지": "결론", "내용": "하나님이 우리를 기업에 합당하게 하셨다. 빛 가운데서 성도의 기업을 함께 누리게 하셨다. 이 모든 것이 아버지의 은혜이다. 오늘 그 아버지께 감사를 드리자", "예화_적용": "오늘 하루를 시작하며 기업을 주신 아버지께 감사 기도를 드려라. 감사가 기쁨의 하루를 열어준다"}
