    {"원어": "πρωτότοκος (프로토토코스)", "의미_문법": "먼저 나신 자 - 형용사(명사적). 첫 번째로 태어난, 탁월한 지위를 가진 자", "설교포인트": "먼저 나신 자는 시간적 순서가 아닌 우위와 권위를 나타낸다. 그리스도는 모든 창조물보다 탁월하고 우월하신 분이시다"},
    {"원어": "πάσης κτίσεως (파세스 크티세오스)", "의미_문법": "모든 창조물 - 속격 구. 모든 피조물의 집합", "설교포인트": "모든 창조물에 대한 그리스도의 탁월성을 강조한다. 창조물에 속하지 않으시고 창조물을 초월하신 분이시다"}
