    {"항목": "에이콘의 헬라 철학적 배경", "내용": "헬라 철학에서 에이콘은 원본의 완전한 반영을 의미했다. 필론은 로고스를 하나님의 에이콘으로 불렀다. 바울은 이 개념을 그리스도에게 적용하여 그리스도가 보이지 않는 하나님의 완전한 표현임을 선포한다", "목회적활용": "문화적 철학 개념을 복음적으로 재정의하여 사용하는 바울의 방법에서 상황화의 원리를 배운다"}
