  "표8_상담적용": [
    {"상황": "삶이 혼란스럽고 무너질 것 같은 분", "성경원리": "만물이 그리스도 안에서 함께 선다. 우주의 유지자이신 그리스도가 우리의 삶도 붙드신다", "실제적용": "혼란한 상황도 그리스도 안에서 의미와 질서를 찾을 수 있음을 가르쳐라. 그리스도께 삶의 통제권을 맡기도록 권면하라"},
    {"상황": "하나님이 계신지 의심되는 분", "성경원리": "그리스도가 만물보다 먼저 계시고 만물을 유지하신다. 우주의 존재 자체가 그분의 존재를 증거한다", "실제적용": "창조의 경이로움을 함께 바라보게 하라. 자연의 질서와 아름다움이 창조주 그리스도를 증거한다고 가르쳐라"}
  ],
  "표9_교차참조": [
    {"구절": "요 1:1-2", "연결점": "태초에 말씀이 계시니라 이 말씀이 하나님과 함께 계셨으니 — 그리스도의 선재성", "구분": "신약"},
    {"구절": "요 8:58", "연결점": "아브라함이 나기 전부터 내가 있느니라 — 그리스도 자신의 선재성 선언", "구분": "신약"},
    {"구절": "히 1:3", "연결점": "그의 능력의 말씀으로 만물을 붙드시며 — 그리스도의 우주 유지", "구분": "신약"},
    {"구절": "시 90:2", "연결점": "산이 생기기 전 땅과 세계도 주께서 조성하시기 전 곧 영원부터 영원까지 주는 하나님이시니이다", "구분": "구약"},
    {"구절": "미 5:2", "연결점": "그의 근본은 태초에, 영원에 있느니라 — 그리스도의 선재성에 관한 예언", "구분": "구약"},
    {"구절": "행 17:28", "연결점": "우리가 그를 힘입어 살며 기동하며 존재하느니라 — 그리스도 안에서의 존재", "구분": "신약"},
    {"구절": "히 13:8", "연결점": "예수 그리스도는 어제나 오늘이나 영원토록 동일하시니라 — 그리스도의 영원한 불변성", "구분": "신약"},
    {"구절": "사 44:6", "연결점": "나는 처음이요 나는 마지막이라 나 외에 다른 신이 없느니라 — 하나님의 영원하심", "구분": "구약"}
  ]
