    {"항목": "우주적 화목의 범위", "내용": "땅과 하늘 모든 것을 화목케 하신다는 것은 화목의 우주적 범위를 나타낸다. 죄로 인해 왜곡된 우주적 질서가 그리스도를 통해 회복된다", "목회적활용": "구원은 개인적 차원을 넘어 우주적 차원의 회복을 포함한다. 창조 세계의 회복도 복음의 일부이다"}
