    {"교리": "우주적 구속", "설명": "그리스도의 화목은 인간만이 아닌 만물을 포함한다. 창조 세계 전체가 그리스도를 통한 회복을 향하고 있다. 이것은 새 창조의 신학과 연결된다", "관련구절": "롬 8:19-22, 엡 1:10, 계 21:5, 사 65:17"}
