    {"구분": "이사야의 평화의 종", "내용": "사 53:5의 그가 찔림은 우리의 허물 때문이요 그가 상함은 우리의 죄악 때문이라 그가 징계를 받으므로 우리는 평화를 누린다는 예언이 십자가 화목의 예표이다", "그리스도연결": "예수님이 이사야의 고난받는 종으로 오셔서 십자가에서 평화를 이루셨다(사 53:5, 골 1:20)"}
