    {"구분": "다니엘의 비밀과 계시", "내용": "다니엘에게 하나님이 꿈의 비밀을 계시하신 것(단 2:19-30)이 하나님이 성도들에게 복음의 비밀을 계시하시는 것의 예표이다", "그리스도연결": "다니엘이 본 비밀의 돌이 그리스도이시다(단 2:44-45). 모든 구약의 비밀이 그리스도 안에서 성취된다"}
