    {"영어원문": "But now is made manifest to his saints — the thing itself, and the full revelation of it, is now made known to all his people.", "한국어번역": "이제는 그의 성도들에게 나타났으니 — 그 자체와 그것의 완전한 계시가 이제 그의 모든 백성에게 알려졌다.", "핵심통찰": "복음의 비밀은 선택된 소수의 전유물이 아니라 모든 성도에게 공개된 하나님의 선물이다"}
