    {"항목": "그리스도의 내주 신학", "내용": "그리스도가 신자 안에 거하신다는 내주 신학은 바울의 고유한 신학적 통찰이다(갈 2:20). 외부의 율법이 아닌 내주하시는 그리스도가 변화의 근원이다", "목회적활용": "변화는 외적 규율이 아닌 내주하시는 그리스도로 말미암는다. 그리스도와의 연합이 변화의 핵심이다"}
