    {"원어": "ἀγωνιζόμενος (아고니조메노스)", "의미_문법": "힘을 다하여 - 현재 분사 중간. 선수처럼 경쟁하며 싸우다", "설교포인트": "아곤(경기)에서 온 단어이다. 사역은 선수처럼 전력을 다하는 것이다. 반쪽 노력이 아닌 전력 질주이다"},
    {"원어": "ἐνέργειαν (에네르게이안)", "의미_문법": "역사/능력 - 명사 여성 단수 대격. 에너지, 활동력", "설교포인트": "수고의 능력은 내 속에서 역사하시는 이의 능력이다. 나의 수고이지만 그 에너지의 원천은 하나님이시다"}
