    {"원어": "ἑώρακαν (헤오라칸)", "의미_문법": "보지 못한 - 완료 능동 직설법 3인칭 복수. 본 적이 없는", "설교포인트": "만난 적 없는 이들을 위한 기도가 가능하다. 기도는 물리적 거리를 초월한 영적 돌봄이다"}
