    {"항목": "바울의 미방문 교회를 향한 사역", "내용": "바울은 골로새와 라오디게아를 직접 방문하지 않았지만 그들을 위해 기도하고 편지를 보냈다. 현대적 의미에서 원격 사역의 신약적 모범이다", "목회적활용": "직접 만남이 없어도 기도와 말씀을 통한 목회적 돌봄은 가능하다"}
