    {"영어원문": "And for them at Laodicea — he was equally concerned for churches which he had never visited.", "한국어번역": "라오디게아에 있는 자들을 위해서도 — 그는 자신이 방문한 적이 없는 교회들에 대해서도 동등한 관심을 가졌다.", "핵심통찰": "목회적 사랑은 직접 아는 자들에게만 제한되지 않는다"}
