    {"구분": "감추인 만나", "내용": "광야에서 하나님이 하늘에서 내려주신 만나가 감추어진 보화로서의 그리스도의 예표이다(출 16:15)", "그리스도연결": "예수님이 하늘에서 내려온 참 만나이시다(요 6:51). 그 안에 생명의 모든 자양분이 있다"}
