    {"대지": "서론", "내용": "사람들은 지혜와 지식을 위해 많은 것을 지불한다. 학교에 가고 책을 읽고 세미나에 참석한다. 그러나 바울은 모든 지혜와 지식의 보화가 그리스도 안에 있다고 한다. 가장 귀한 보화가 이미 우리에게 있다", "예화_적용": "집 뒤뜰에 금광이 있는데 모르고 살다가 발견한 사람처럼, 그리스도 안에 이미 모든 보화가 있다"},
    {"대지": "1대지: 모든 지혜의 보화가 그 안에 (지혜)", "내용": "세상의 지혜도, 하늘의 지혜도 모두 그리스도 안에 있다. 어떤 상황에서든 그리스도 안에서 지혜를 구하면 얻을 수 있다. 그리스도가 모든 지혜의 근원이시다", "예화_적용": "모든 강이 바다에서 오듯, 모든 참 지혜는 그리스도에게서 온다"},
    {"대지": "2대지: 모든 지식의 보화가 그 안에 (지식)", "내용": "인간이 추구하는 모든 참 지식도 그리스도 안에 있다. 세상이 제공하는 지식은 부분적이지만 그리스도 안의 지식은 충만하다", "예화_적용": "사전이 모든 단어를 담고 있듯, 그리스도 안에 모든 참 지식이 담겨있다"},
    {"대지": "3대지: 감추어진 보화를 발굴하는 삶 (탐구)", "내용": "보화는 감추어져 있다. 발굴해야 한다. 기도와 말씀 묵상으로 그리스도 안에 감추어진 보화를 계속 발굴해야 한다. 평생 캐도 다 캘 수 없는 풍성한 보화가 있다", "예화_적용": "광부가 광산에서 계속 금을 캐듯, 그리스도 안에서 계속 지혜와 지식의 보화를 캐내라"},
    {"대지": "결론", "내용": "그리스도 안에 지혜와 지식의 모든 보화가 있다. 이 보화를 캐내는 것이 신앙 생활이다. 이단이나 세상에서 지식을 찾지 말고 그리스도 안에서 찾자", "예화_적용": "오늘 그리스도 안에서 어떤 보화를 발굴할 것인가 결단하라. 말씀 앞에 앉아 보화를 캐는 하루가 되라"}
