    {"항목": "받음과 행함의 연결", "내용": "그리스도를 받았으니 그 안에서 행하라는 구조가 신앙과 생활의 연결을 보여준다. 받음(구원)이 행함(삶)으로 이어져야 한다. 신앙은 삶으로 표현되어야 한다", "목회적활용": "구원받은 것이 삶의 변화로 이어지도록 가르쳐야 한다. 받은 것을 살아내는 것이 신앙이다"}
