    {"구분": "다윗의 하나님 앞에서의 삶", "내용": "다윗이 하나님 앞에서 온전한 마음으로 살아간 것(왕상 11:4)이 그리스도 안에서 행하는 삶의 구약 원형이다", "그리스도연결": "그리스도가 참 다윗으로 오셔서 완전한 하나님 앞에서의 삶을 사셨다. 우리도 그리스도 안에서 그 삶에 동참한다"}
