    {"영어원문": "Walk ye in him — continue in the faith of Christ, and live in a manner becoming his disciples.", "한국어번역": "그 안에서 행하라 — 그리스도의 믿음 안에서 계속하고 그의 제자에 걸맞은 방식으로 살아라.", "핵심통찰": "그리스도 안에서 산다는 것은 제자로서의 삶 전체를 그 안에서 영위하는 것이다"}
