    {"구분": "대제사장의 예복의 충만함", "내용": "대제사장이 이스라엘 전체를 대표하는 충만한 예복을 입은 것이 그리스도 안에 신성의 충만이 거하는 것의 상징적 예표이다", "그리스도연결": "그리스도가 참 대제사장으로 하나님의 충만함을 인류 앞에 나타내셨다(히 4:14-16)"}
