    {"영어원문": "For in him dwelleth all the fulness of the Godhead bodily — not the fulness of grace only, but of the Godhead itself, the divine nature and perfections.", "한국어번역": "그 안에는 신성의 모든 충만이 육체로 거하시고 — 단지 은혜의 충만뿐만이 아니라 신성 자체, 신적 본성과 완전함들이.", "핵심통찰": "그리스도 안에 있는 것은 신적 특성의 일부가 아닌 신성 자체의 완전한 충만이다"},
    {"영어원문": "Bodily — not only mystically, as the head is in the members, but substantially, in his own divine person in a human body.", "한국어번역": "육체로 — 신비적으로만이 아니라, 인간의 몸 안에 있는 그 자신의 신적 인격 안에서 실질적으로.", "핵심통찰": "성육신은 상징이 아닌 실질적 사실이다"}
