    {"영어원문": "Not by hands of man, but by the operation of the Spirit — it is the circumcision of Christ, of which he is both the author and the matter.", "한국어번역": "사람의 손으로 한 것이 아니라 성령의 역사로 — 그것은 그리스도의 할례이며 그가 그것의 저자이자 내용이시다.", "핵심통찰": "영적 변화는 인간의 의식이 아닌 그리스도의 역사로 이루어진다"}
