    {"대지": "2대지: 육적 몸을 벗는 내적 변화 (성화)", "내용": "그리스도의 할례는 육적 몸을 벗는 것이다. 옛 자아의 죄성이 제거되는 내적 변화이다. 이것이 참 성화이다", "예화_적용": "낡은 옷을 벗고 새 옷을 입듯, 그리스도의 할례는 옛 자아를 벗고 새 자아를 입는 것이다"},
    {"대지": "3대지: 구약 할례의 신약적 완성 (구속사)", "내용": "그리스도의 할례가 구약의 외적 할례를 완성했다. 구속사의 진보이다. 외적 표시에서 내적 실재로 나아간 것이다", "예화_적용": "초등학교 공부가 대학 공부의 기초가 되듯, 구약의 할례가 신약의 마음 할례의 기초가 되었다"},
    {"대지": "결론", "내용": "그리스도 안에서 손으로 하지 않은 참 할례를 받았다. 외적 의식이 아닌 내적 변화가 일어난 것이다. 이 변화의 확신으로 살아가자", "예화_적용": "오늘 내 안에서 육적 몸이 벗겨지는 경험이 있는지 돌아보라. 그리스도의 할례가 내 삶에 역사하고 있는가"}
